// Reload refetches the object from the database
// using the primary keys with an executor.
func (o *Deck) Reload(ctx context.Context, exec boil.ContextExecutor) error {
	ret, err := FindDeck(ctx, exec, o.DeckID)
	if err != nil {
		return err
	}

	*o = *ret
	return nil
}

// ReloadAll refetches every row with matching primary key column values
// and overwrites the original object slice with the newly updated slice.
func (o *DeckSlice) ReloadAll(ctx context.Context, exec boil.ContextExecutor) error {
	if o == nil || len(*o) == 0 {
		return nil
	}

	slice := DeckSlice{}
	var args []any
	for _, obj := range *o {
		pkeyArgs := queries.ValuesFromMapping(reflect.Indirect(reflect.ValueOf(obj)), deckPrimaryKeyMapping)
		args = append(args, pkeyArgs...)
	}

	sql := "SELECT \"decks\".* FROM \"decks\" WHERE " +
		strmangle.WhereClauseRepeated(string(dialect.LQ), string(dialect.RQ), 1, deckPrimaryKeyColumns, len(*o))

	q := queries.Raw(sql, args...)

	err := q.Bind(ctx, exec, &slice)
	if err != nil {
		return errors.Wrap(err, "models: unable to reload all in DeckSlice")
	}

	*o = slice

	return nil
}

// DeckExists checks if the Deck row exists.
func DeckExists(ctx context.Context, exec boil.ContextExecutor, deckID string) (bool, error) {
	var exists bool
	sql := "select exists(select 1 from \"decks\" where \"deck_id\"=$1 limit 1)"

	if boil.IsDebug(ctx) {
		writer := boil.DebugWriterFrom(ctx)
		fmt.Fprintln(writer, sql)
		fmt.Fprintln(writer, deckID)
	}
	row := exec.QueryRowContext(ctx, sql, deckID)

	err := row.Scan(&exists)
	if err != nil {
		return false, errors.Wrap(err, "models: unable to check if decks exists")
	}

	return exists, nil
}

// Exists checks if the Deck row exists.
func (o *Deck) Exists(ctx context.Context, exec boil.ContextExecutor) (bool, error) {
	return DeckExists(ctx, exec, o.DeckID)
}
